package org.firstinspires.ftc.teamcode.subsystems;

import com.pedropathing.math.Pose;
import com.pedropathing.math.Velocity;

import org.firstinspires.ftc.teamcode.config.Field;
import org.firstinspires.ftc.teamcode.config.MatchState;
import org.firstinspires.ftc.teamcode.config.Tuned;

// Generated by refract-suite ftc-construct. Solves both launchers against the own-alliance CELL on the
// robot's side of y = 72. The turrets share one geared yaw, so the yaw command is midway between the
// two launchers' angles and each launcher keeps a small residual error (reported).
// Velocity: Pedro's localizer velocity is treated as field-frame (Velocity.toTwist(heading) exists to
// convert it to robot frame); confirm on the robot with prerequisites E-10. Omega in rad/s.
public final class AutoAim {
    public static final class Solution {
        public boolean valid = false;
        public String problem = "";
        public double cellX, cellY;
        public double frontDistance, backDistance;
        public double frontYawDeg, backYawDeg;      // each turret's own angle relative to the robot
        public double backAsFrontDeg;               // back requirement expressed in front-turret degrees
        public double commandFrontDeg;              // shared yaw command (midway)
        public double frontErrorDeg, backErrorDeg;  // residual at the current yaw position
        public double rateFeedforwardDeg;
        public boolean locked;
        public boolean solved;                      // geometry computed (may still be invalid: midway out of travel)
        public boolean frontReachable, backReachable;
    }

    private AutoAim() {}

    public static double distance(double fromX, double fromY, double toX, double toY) {
        return Math.hypot(toX - fromX, toY - fromY);
    }

    public static double[] pivot(Pose pose, double bodyX, double bodyY) {
        double c = Math.cos(pose.heading()), s = Math.sin(pose.heading());
        return new double[]{pose.x() + c * bodyX - s * bodyY, pose.y() + s * bodyX + c * bodyY};
    }

    // half the angle the 20 in CELL opening subtends at this distance
    public static double toleranceDeg(double distance) {
        return 0.5 * Math.toDegrees(Math.atan(Field.CELL_HALF_WIDTH / distance));
    }

    public static Solution solve(Pose pose, Velocity fieldVelocity, MatchState.Alliance alliance,
                                 double currentFrontDeg, double distanceTrim, double angleTrimDeg) {
        Solution s = new Solution();
        if (alliance == null) return fail(s, "alliance unknown (INIT the correct auto, or pick in teleop INIT)");
        if (!Tuned.isSet(Tuned.frontPivotX, Tuned.frontPivotY, Tuned.backPivotX, Tuned.backPivotY)) {
            return fail(s, "turret pivot offsets not set (C-3)");
        }
        if (!Yaw.calibrated()) return fail(s, "yaw not measured (G-1 Yaw Tuner)");
        double[] cell = Field.targetCell(alliance, pose.y());
        if (!Tuned.isSet(cell[0], cell[1])) return fail(s, "CELL coordinates not set (H-1)");
        s.cellX = cell[0];
        s.cellY = cell[1];

        double[] fp = pivot(pose, Tuned.frontPivotX, Tuned.frontPivotY);
        double[] bp = pivot(pose, Tuned.backPivotX, Tuned.backPivotY);
        double vx = fieldVelocity.vx, vy = fieldVelocity.vy;

        // No shot lead: the robot is stopped when it fires. The velocity only feeds the turret's rate feedforward,
        // so it keeps the aim on the CELL while the robot drives or turns between shots.
        double ftx = cell[0], fty = cell[1];
        double btx = cell[0], bty = cell[1];

        s.frontDistance = distance(fp[0], fp[1], ftx, fty) + distanceTrim;
        s.backDistance = distance(bp[0], bp[1], btx, bty) + distanceTrim;
        // + the yaw trim each launcher scored with in programs 8 / 9 (its own turret degrees)
        s.frontYawDeg = Field.wrapDeg(Math.toDegrees(Math.atan2(fty - fp[1], ftx - fp[0]) - pose.heading())) + angleTrimDeg + trim(Tuned.frontYawTrimDeg);
        double back = Field.wrapDeg(Math.toDegrees(Math.atan2(bty - bp[1], btx - bp[0]) - pose.heading())) + angleTrimDeg + trim(Tuned.backYawTrimDeg);
        // choose the back angle (in back degrees) nearest to where the gearing puts it for the front angle
        double ref = Yaw.frontToBackDeg(s.frontYawDeg);
        while (back - ref > 180) back -= 360;
        while (back - ref < -180) back += 360;
        s.backYawDeg = back;
        s.backAsFrontDeg = Yaw.backToFrontDeg(back);
        s.commandFrontDeg = (s.frontYawDeg + s.backAsFrontDeg) / 2.0;
        s.frontReachable = Yaw.inLimits(s.frontYawDeg);
        s.backReachable = Yaw.inLimits(s.backAsFrontDeg);

        // line-of-sight rate from robot translation, minus chassis spin, in deg/s (DECODE feedforward)
        double dx = ftx - fp[0], dy = fty - fp[1];
        double d2 = dx * dx + dy * dy;
        double los = d2 > 1e-3 ? Math.toDegrees((-dx * vy + dy * vx) / d2) : 0;
        s.rateFeedforwardDeg = los - Math.toDegrees(fieldVelocity.omega);

        if (!Double.isNaN(currentFrontDeg)) {
            s.frontErrorDeg = currentFrontDeg - s.frontYawDeg;
            s.backErrorDeg = Yaw.frontToBackDeg(currentFrontDeg) - s.backYawDeg;
            s.locked = Math.abs(s.frontErrorDeg) <= toleranceDeg(s.frontDistance)
                    && Math.abs(s.backErrorDeg) <= toleranceDeg(s.backDistance);
        }
        s.solved = true;
        if (!Yaw.inLimits(s.commandFrontDeg)) return fail(s, "CELL outside yaw travel: turn the robot");
        s.valid = true;
        return s;
    }

    // A yaw trim past this is not aim error but a turret zeroed while turned (TurretZero): never saved, never used
    public static final double MAX_TRIM_DEG = 10;

    // no trim measured yet = none; an old one past MAX_TRIM_DEG (saved before that check) = none
    private static double trim(double deg) {
        return Double.isNaN(deg) || Math.abs(deg) > MAX_TRIM_DEG ? 0 : deg;
    }

    public static Solution invalid(String why) {
        return fail(new Solution(), why);
    }

    private static Solution fail(Solution s, String why) {
        s.valid = false;
        s.locked = false;
        s.problem = why;
        return s;
    }
}
